"use client";
import { AddInterestedEvent } from "@/action";
import { useAuth } from "@/hooks/useAuth";
import { useRouter } from "next/navigation";
import { useState, useTransition } from "react";

export default function ActionButton({
  eventId,
  interestedUserId,
  fromDetails,
}) {
  const { auth } = useAuth();
  const router = useRouter();

  console.log("The auth is", auth);
  const isInterested = interestedUserId?.find((id) => id === auth?.useData?.id);
  const [interested, setInterested] = useState(isInterested);
  const [isPending, startTransition] = useTransition();

  const toggleInterest = async () => {
    if (auth?.userData) {
      await AddInterestedEvent(eventId, auth?.userData?.id);
      setInterested(!interested);
    } else {
      // router.push("/login");
    }
  };
  const markGoing = () => {
    if (auth?.useData) {
      router.push("/payment");
    } else {
      router.push("/login");
    }
  };

  return (
    <div className={`w-full flex gap-4 mt-4 ${fromDetails && "flex-1"}`}>
      <button
        onClick={() =>
          startTransition(() => {
            toggleInterest();
          })
        }
        className={`w-full ${
          interested && "bg-indigo-600 hover:bg-indigo-800"
        }`}
      >
        Interested
      </button>
      <button
        onClick={markGoing}
        className=" text-center w-full bg-[#464849] py-2 px-2 rounded-md border border-[#5F5F5F]/50 shadow-sm cursor-pointer hover:bg-[#3C3D3D] transition-colors active:translate-y-1"
      >
        Going
      </button>
    </div>
  );
}
